ll check(ll k)
{
    if(k < 2) return 0;
    for(int i = 2;i <= sqrt(k);i++) {
        if(k % i == 0) return 0;
    }
    return 1;
}

ll solve(ll n)
{
    ll cnt = 0;
    for(int i = 1;i <= sqrt(n);i++) {
        if(n % i == 0) {
            if(check(i)) cnt++;
            if(n / i != i) {
                if(check(n/i)) cnt++;
            }
            if(cnt >= 3) return 1;
        }
    }
    return 0;
}
ll ktradx(ll n)
{
    ll k = 0;
    ll n1 = n;
    while(n > 0) {
        ll tmp = n % 10;
        k = k * 10 + tmp;
        n /= 10;
    }
    if(n1 == k) return 1;
    else return 0;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    #define taskname "FBALL"
    //if(fopen(taskname ".inp","r"))
    //{
        freopen(taskname ".inp","r",stdin);
        freopen(taskname ".out","w",stdout);
    //}
    ll a = 1e7,b = 1e9;
    for(int i = a;i <= b;i++) {
        if(solve(i) && ktradx(i)) cout << i << ' ';
    }
    return 0;
}
